From 5f739e29fb7c9d7239b5a086b05496ef7d36aa67 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:14:50 +0100
Subject: [PATCH] x11window: pick the Flatpak or native desktop file the window
 runs from

When an app is installed both natively and as a Flatpak, both desktop
files share its StartupWMClass and the first one won for every window.
Now the window's systemd unit decides which of the two it belongs to.

BUG: 498875
---
 src/x11window.cpp | 37 ++++++++++++++++++++++++++++++++++---
 1 file changed, 34 insertions(+), 3 deletions(-)

diff --git a/src/x11window.cpp b/src/x11window.cpp
index 297e3be8d0..a7097c0169 100644
--- a/src/x11window.cpp
+++ b/src/x11window.cpp
@@ -44,6 +44,9 @@
 // xcb
 #include <xcb/xcb_icccm.h>
 // system
+#if HAVE_SYSTEMD
+#include <systemd/sd-login.h>
+#endif
 #include <unistd.h>
 // c++
 #include <cmath>
@@ -101,6 +104,19 @@ const NET::WindowTypes SUPPORTED_UNMANAGED_WINDOW_TYPES_MASK = NET::NormalMask
  * \brief The Client class encapsulates a window decoration frame.
  */

+static QString systemdUserUnit(pid_t pid)
+{
+#if HAVE_SYSTEMD
+    char *unit = nullptr;
+    if (pid > 0 && sd_pid_get_user_unit(pid, &unit) >= 0) {
+        const QString unitName = QString::fromUtf8(unit);
+        free(unit);
+        return unitName;
+    }
+#endif
+    return QString();
+}
+
 /**
  * This ctor is "dumb" - it only initializes data. All the real initialization
  * is done in manage().
@@ -417,11 +433,26 @@ bool X11Window::manage(xcb_window_t w, bool isMapped)
     }
     if (desktopFileName.isEmpty() && !resourceName().isEmpty()) {
         // Fallback to StartupWMClass for legacy apps
-        const auto service = KApplicationTrader::query([this](const KService::Ptr &service) {
+        const auto services = KApplicationTrader::query([this](const KService::Ptr &service) {
             return service->property<QString>("StartupWMClass").compare(resourceName(), Qt::CaseInsensitive) == 0;
         });
-        if (!service.isEmpty()) {
-            desktopFileName = service.constFirst()->desktopEntryName();
+        if (!services.isEmpty()) {
+            KService::Ptr service = services.constFirst();
+            const QString unit = services.size() > 1 ? systemdUserUnit(pid()) : QString();
+            if (!unit.isEmpty()) {
+                // The same app can be installed both natively and as a Flatpak, pick the one this window runs from
+                const auto it = std::find_if(services.cbegin(), services.cend(), [&unit](const KService::Ptr &service) {
+                    const QString flatpakId = service->property<QString>("X-Flatpak");
+                    if (flatpakId.isEmpty()) {
+                        return !unit.startsWith(QLatin1String("app-flatpak-"));
+                    }
+                    return unit.startsWith(QLatin1String("app-flatpak-") + flatpakId + QLatin1Char('-'));
+                });
+                if (it != services.cend()) {
+                    service = *it;
+                }
+            }
+            desktopFileName = service->desktopEntryName();
         }
     }
     setDesktopFileName(rules()->checkDesktopFile(desktopFileName, true));
